// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 _val, uint256 _lockTime, uint256 _am) public {
        _val = bound(_val, 0, type(uint256).max);
        _lockTime = bound(_lockTime, 0, 1000000);
        _am = bound(_am, 0, 1 ether);
        vm.assume(_val > 0);

        c.SetMinSum(_val);
        c.Initialized();

        (bool success, ) = address(c).call{value: _am}("");
        if (success) {
            c.Collect(_am);
        }

        assertTrue(c.MinSum() >= _val);
    }
}

